export const MARKDOWN_STYLE_NAMES: MarkdownStyleName[] = [...MARKDOWN_STYLE_PRESET_NAMES, 'custom']

export const COLOR_ROLES: ColorRole[] = ['primary', 'secondary']

export const MARKDOWN_SECTIONS: MarkdownSection[] = [
    'title1',
